def seed_database() -> None:
    """Insert 25 numbered items when the table is empty."""
    db = session_factory()
    try:
        if db.scalar(select(func.count()).select_from(Item)) == 0:
            for i in range(1, 26):
                db.add(Item(id=i, name=f"Item {i}"))
            db.commit()
    finally:
        db.close()
